UPDATE test_case
SET latest_bug_task_id = #{bugTaskId}
WHERE id = #{id} AND workspace_id = #{workspaceId}

mapper.select:
SELECT * FROM test_case
WHERE workspace_id = #{workspaceId}
ORDER BY created_at ASC, id ASC

mapper.sql:
WHERE c.workspace_id = #{q.workspaceId} AND c.req_id = #{q.reqId}

   AND c.latest_status IS NULL 
   AND c.latest_status = #{q.status} 


   AND (c.module IS NULL OR c.module = '') 
   AND c.module = #{q.module} 


   AND (c.priority IS NULL OR c.priority = '') 
   AND c.priority = #{q.pri} 

 AND c.latest_by = #{q.owner} 
 AND c.latest_bug_task_id IS NOT NULL 

  AND (c.title LIKE CONCAT('%', #{q.q}, '%')
       OR c.precondition LIKE CONCAT('%', #{q.q}, '%')
       OR c.module LIKE CONCAT('%', #{q.q}, '%')
       OR c.latest_note LIKE CONCAT('%', #{q.q}, '%')
       OR c.steps LIKE CONCAT('%', #{q.q}, '%')
       OR d.title LIKE CONCAT('%', #{q.q}, '%')
       OR t.title LIKE CONCAT('%', #{q.q}, '%'))

mapper.select:
SELECT 'case' AS type, c.id, c.title, c.req_id AS reqId, r.name AS reqName, c.latest_status AS status, c.module AS extra, c.updated_at AS updatedAt FROM test_case c LEFT JOIN requirement r ON r.id = c.req_id AND r.workspace_id = c.workspace_id WHERE c.workspace_id = #{workspaceId} AND ( LOCATE(LOWER(#{q}), LOWER(c.title)) > 0 OR LOCATE(LOWER(#{q}), LOWER(c.module)) > 0 OR LOCATE(LOWER(#{q}), LOWER(c.precondition)) > 0 )
AND NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = c.workspace_id AND pm.project_id = c.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none')
ORDER BY c.updated_at DESC LIMIT #{limit}

